package com.example.editor.textual.web;
import java.net.URI;import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import com.example.editor.textual.definition.*;import com.example.editor.validation.persistence.StoredCanonicalDocument;
@RestController @RequestMapping("/api/textual-syntax-styles") public class TextualSyntaxStyleController{private final TextualSyntaxStyleService service;/** Descripción: Inicializa una instancia de TextualSyntaxStyleController con sus dependencias y datos de entrada. Entradas: s: dato de entrada necesario para la operación. Salida: deja la instancia inicializada y lista para su uso. */ public TextualSyntaxStyleController(TextualSyntaxStyleService s){service=s;}/** Descripción: Obtiene la información correspondiente a «list» dentro de TextualSyntaxStyleController. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @GetMapping public List<TextualSyntaxStyleDefinition>list(){return service.list().stream().map(StoredCanonicalDocument::document).toList();}/** Descripción: Crea o prepara el resultado de «create» dentro de TextualSyntaxStyleController. Entradas: m: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ @PostMapping public ResponseEntity<TextualSyntaxStyleDefinition>create(@RequestBody TextualSyntaxStyleDefinition m){var s=service.create(m);return ResponseEntity.created(URI.create("/api/textual-syntax-styles/"+m.id())).header(HttpHeaders.ETAG,s.etag()).body(s.document());}@GetMapping("/{id}")public ResponseEntity<TextualSyntaxStyleDefinition>find(@PathVariable String id){var s=service.find(id);return ResponseEntity.ok().header(HttpHeaders.ETAG,s.etag()).body(s.document());}@PutMapping("/{id}")public ResponseEntity<TextualSyntaxStyleDefinition>replace(@PathVariable String id,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String e,@RequestBody TextualSyntaxStyleDefinition m){var s=service.replace(id,m,e);return ResponseEntity.ok().header(HttpHeaders.ETAG,s.etag()).body(s.document());}@DeleteMapping("/{id}")public ResponseEntity<Void>delete(@PathVariable String id,@RequestHeader(value=HttpHeaders.IF_MATCH,required=false)String e){service.delete(id,e);return ResponseEntity.noContent().build();}}
